const fs = require('fs');
const path = require('path');

// Function to parse different date formats
function parseDate(dateStr) {
  // Handle ISO format (YYYY-MM-DDTHH:mm:ssZ)
  if (dateStr.includes('T')) {
    return new Date(dateStr);
  }

  // Handle DD/MM/YYYY format
  if (dateStr.includes('/')) {
    const [day, month, year] = dateStr.split('/');
    return new Date(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T00:00:00Z`);
  }

  return new Date(dateStr);
}

// Function to parse value field, converting nulls to 0
function parseValue(valueStr) {
  if (!valueStr || valueStr === '' || valueStr === 'N/A' || valueStr === 'null') {
    return 0;
  }
  return parseFloat(valueStr);
}

// Function to clean CSV content
function cleanCSV(content, filename) {
  const lines = content.trim().split('\n');
  let cleanedLines = [];

  // Process each line
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i].trim();

    // Remove trailing comma if present
    if (line.endsWith(',')) {
      line = line.slice(0, -1);
    }

    // Skip empty lines
    if (!line) continue;

    // Skip duplicate header rows (except the first one)
    if (i > 0 && line === 'event_id,event_ts,user_id,event_type,value') {
      console.log(`Skipping duplicate header in ${filename} at line ${i + 1}`);
      continue;
    }

    cleanedLines.push(line);
  }

  return cleanedLines;
}

// Function to convert CSV to events
function csvToEvents(csvLines) {
  const events = [];
  const headers = csvLines[0].split(',');

  for (let i = 1; i < csvLines.length; i++) {
    const values = csvLines[i].split(',');

    if (values.length >= 5) {
      const event = {
        event_id: values[0],
        event_ts: parseDate(values[1]).toISOString(),
        user_id: values[2],
        event_type: values[3],
        value: parseValue(values[4])
      };

      events.push(event);
    }
  }

  return events;
}

// Function to send event to Moose
async function sendEvent(event) {
  try {
    const response = await fetch('http://localhost:4000/ingest/Event', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(event)
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`HTTP ${response.status}: ${errorText}`);
    }

    return true;
  } catch (error) {
    console.error(`Failed to send event ${event.event_id}:`, error.message);
    return false;
  }
}

// Main function
async function main() {
  const csvDir = '/data/csv';
  const csvFiles = [
    'events_01.csv',
    'events_02.csv',
    'events_03.csv',
    'events_04.csv',
    'events_05.csv'
  ];

  let totalEvents = 0;
  let successfulEvents = 0;

  for (const filename of csvFiles) {
    const filepath = path.join(csvDir, filename);

    try {
      console.log(`Processing ${filename}...`);

      const content = fs.readFileSync(filepath, 'utf8');
      const cleanedLines = cleanCSV(content, filename);
      const events = csvToEvents(cleanedLines);

      console.log(`Found ${events.length} events in ${filename}`);
      totalEvents += events.length;

      // Send each event
      for (const event of events) {
        const success = await sendEvent(event);
        if (success) {
          successfulEvents++;
          console.log(`✓ Loaded event ${event.event_id}`);
        }
      }

    } catch (error) {
      console.error(`Error processing ${filename}:`, error.message);
    }
  }

  console.log(`\nSummary:`);
  console.log(`Total events found: ${totalEvents}`);
  console.log(`Successfully loaded: ${successfulEvents}`);
  console.log(`Failed: ${totalEvents - successfulEvents}`);
}

main().catch(console.error);

